import data from "./data.json"
import {
  Page,
  Section,
  Grid,
  Group,
  Text,
  Stat,
  DataTable,
  List,
  KV,
  FigureStrip,
  Figure,
  FigureImage,
  FigureLabel,
  FigureText,
} from "@/components/report"

export default function Report() {
  const { kpis, products, chains, stages, patterns, issues, suggestions } = data as any

  const stepText = (step: any) =>
    [step.content, step.action, step.inputs > 0 ? `输入 ${step.inputs} 项` : null]
      .filter(Boolean)
      .join(" · ")

  return (
    <Page
      title={data.title}
      meta={["4 款出行 App", "2026 年 9 月版本"]}
    >
      <Section title="背景信息" description="任务、范围与日期">
        <KV
          labelCols={2}
          items={[
            { label: "分析任务", value: data.task },
            { label: "对比范围", value: data.scope },
            { label: "分析日期", value: data.date },
          ]}
        />
      </Section>

      <Section title="结论" description="四款 App 预订一张单程机票的流程对比">
        <Text className="text-2xl leading-9 font-light">{data.summary}</Text>
      </Section>

      <Section title="核心指标" description="对比范围与主要发现">
        <Grid cols={12} fields={false} className="items-baseline">
          {kpis.map((k: any) => (
            <Stat
              key={k.key}
              span={12 / kpis.length}
              value={k.value}
              unit={k.unit}
              label={k.label}
              captionBelow
              size={k.key === "fewest" ? "lg" : undefined}
              note={k.key === "fewest" ? "最多 9 步(云途)" : undefined}
            />
          ))}
        </Grid>
      </Section>

      <Section title="流程对比" description="每款 App 从首页到支付的总步数与输入项">
        <Grid cols={9} fields={false} className="items-baseline">
          {products.map((p: any) => (
            <Stat
              key={p.name}
              span={2}
              value={p.steps}
              unit="步"
              label={p.name}
              captionBelow
              note={`输入 ${p.inputs} 项 · ${p.verdict}`}
            />
          ))}
        </Grid>
      </Section>

      <Section title="关键环节" description="五个环节在各 App 的做法差异">
        <DataTable
          columns={[
            { key: "stage", label: "环节", span: 1 },
            { key: "yuntu", label: "云途", span: 2 },
            { key: "xinglv", label: "行旅", span: 2 },
            { key: "feiyu", label: "飞鱼", span: 2 },
            { key: "beijixing", label: "北极星", span: 2 },
          ]}
          rows={stages.map((s: any) => ({
            stage: s.stage,
            yuntu: s["云途"],
            xinglv: s["行旅"],
            feiyu: s["飞鱼"],
            beijixing: s["北极星"],
          }))}
        />
      </Section>

      <Section title="共性模式" description="四款 App 中反复出现的做法">
        <List
          numbered
          items={patterns.map((p: any) => ({
            title: p.name,
            description: `${p.comment} · 涉及 ${p.products.join("、")}`,
          }))}
        />
      </Section>

      <Section title="交互链路" description="每款 App 从首页到支付的步骤与截图" className="gap-12">
        {chains.map((chain: any) => (
          <Group key={chain.product} title={`${chain.product} · ${chain.version}`}>
            <FigureStrip>
              {chain.steps.map((step: any) => (
                <Figure key={step.no}>
                  <FigureImage
                    src={step.image}
                    alt={`${chain.product} 第 ${step.no} 步:${step.screen}`}
                  />
                  <FigureLabel>第 {step.no} 步 · {step.screen}</FigureLabel>
                  <FigureText>{stepText(step)}</FigureText>
                </Figure>
              ))}
            </FigureStrip>
          </Group>
        ))}
        <Group title="步骤备注">
          <DataTable
            columns={[
              { key: "product", label: "产品", span: 1 },
              { key: "step", label: "步骤", span: 2 },
              { key: "note", label: "备注", span: 6 },
            ]}
            rows={chains.flatMap((chain: any) =>
              chain.steps
                .filter((step: any) => step.note)
                .map((step: any) => ({
                  product: chain.product,
                  step: `第 ${step.no} 步 · ${step.screen}`,
                  note: step.note,
                }))
            )}
          />
        </Group>
      </Section>

      <Section title="问题明细" description="按严重度排列的 7 个问题">
        <DataTable
          columns={[
            { key: "id", label: "编号", span: 1 },
            { key: "product", label: "产品", span: 1 },
            { key: "step", label: "步骤", span: 1 },
            { key: "title", label: "问题", span: 3 },
            { key: "severity", label: "严重度", span: 1, tone: ["高"] },
            { key: "evidence", label: "依据", span: 2 },
          ]}
          rows={issues.map((i: any) => ({
            id: i.id,
            product: i.product,
            step: `第 ${i.step} 步`,
            title: i.title,
            severity: i.severity,
            evidence: i.evidence,
          }))}
        />
      </Section>

      <Section title="下一步" description="基于对比与问题提出的四条改进建议">
        <List
          numbered
          columns={3}
          items={suggestions.map((s: any) => ({
            title: s.title,
            description: `${s.id} · 依据 ${s.basis.join("、")}`,
          }))}
        />
      </Section>
    </Page>
  )
}

// Build a workspace's Page.tsx with the component library, screenshot it and run
// the program checks. The generator agent runs this after every edit.
//
//   node scripts/shoot.mjs <workspace>
//
// <workspace> holds Page.tsx and data.json. Writes into it:
//   shot.png       the page, 1248px wide (the 1152px frame with a 48px margin)
//   thumb.png      the same at half width (what the judge sees as the overview)
//   tile-N.png     640px slices with 64px overlap (what the judge sees as detail)
//   checks.json    program check results
// Prints the check results; exit code 0 even when checks fail (they are findings).
import fs from "node:fs"
import path from "node:path"
import http from "node:http"
import { build } from "vite"
import react from "@vitejs/plugin-react"
import tailwindcss from "@tailwindcss/vite"
import { chromium } from "playwright-core"
import { createRequire } from "node:module"

const require = createRequire(import.meta.url)

const ws = path.resolve(process.argv[2] ?? ".")
// The component library: the shared one, or a candidate the component agent is working on in <ws>/app.
const APP = fs.existsSync(path.join(ws, "app", "index.html")) ? path.join(ws, "app") : path.resolve(import.meta.dirname, "..", "app")
const OUT = path.join(ws, ".build")
const VIEWPORT = { width: 1440, height: 900 }
const CLIP_X = (VIEWPORT.width - 1152) / 2 - 48
const CLIP_W = 1152 + 96
const TILE_H = 640
const TILE_OVERLAP = 64

const findings = []
const add = (check, msg, line) => findings.push({ check, msg, ...(line && { line }) })

// ---------- source checks on Page.tsx, with line numbers ----------
const src = fs.readFileSync(path.join(ws, "Page.tsx"), "utf8")
const ALLOWED_IMPORT = /^(react|@\/components\/report|@\/components\/ui\/(table|progress|separator|item|chart)|\.\/data\.json)$/
const COLOR = /\b(?:text|bg|border|fill|stroke|from|to|via)-(?:red|green|blue|slate|gray|zinc|neutral|stone|orange|amber|yellow|lime|emerald|teal|cyan|sky|indigo|violet|purple|fuchsia|pink|rose|white|black)\b/
src.split("\n").forEach((line, i) => {
  const n = i + 1
  for (const m of line.matchAll(/from\s+["']([^"']+)["']/g))
    if (!ALLOWED_IMPORT.test(m[1])) add("组件库", `import 了组件库以外的模块 ${m[1]}`, n)
  if (/\bstyle=\{/.test(line)) add("统一刻度", "写了 inline style;尺寸、颜色只能来自组件和规范里的类名", n)
  for (const m of line.matchAll(/\b[\w:-]+-\[[^\]]+\]/g)) add("统一刻度", `任意值类名 ${m[0]}`, n)
  const c = line.match(COLOR)
  if (c) add("统一刻度", `直接写了颜色类名 ${c[0]};颜色只能来自组件(下降、严重用组件的 direction、tone)`, n)
  for (const m of line.matchAll(/\btext-(xs|sm|base|lg|xl|3xl|4xl|5xl|6xl|7xl|8xl|9xl)\b/g)) add("统一刻度", `字号类名 ${m[0]} 不在规范里(只允许结论句的 text-2xl)`, n)
  for (const m of line.matchAll(/<(h[1-6]|p|span|table|ul|ol|li|img|svg|button)\b/g)) add("组件库", `直接写了 <${m[1]}>,应使用组件库组件`, n)
  // The same tags through createElement / jsx() are the same thing written another way.
  for (const m of line.matchAll(/\b(?:createElement|jsxs?)\(\s*["'`]([a-z][a-z0-9]*)["'`]/g)) if (m[1] !== "div") add("组件库", `用 createElement 直接画了 <${m[1]}>,应使用组件库组件`, n)
})

// ---------- build ----------
fs.rmSync(OUT, { recursive: true, force: true })
try {
  await build({
    root: APP,
    base: "./",
    logLevel: "error",
    configFile: false,
    plugins: [
      // Tailwind emits only the classes it finds; point it at the workspace too.
      { name: "workspace-source", enforce: "pre", transform: (code, id) => (id.endsWith("/src/index.css") ? `${code}\n@source "${ws}/Page.tsx";\n` : null) },
      react(),
      tailwindcss(),
    ],
    // The workspace may sit outside this package, so React resolves from here.
    resolve: {
      alias: [
        { find: "@page", replacement: path.join(ws, "Page.tsx") },
        { find: /^react\/jsx-runtime$/, replacement: require.resolve("react/jsx-runtime") },
        { find: /^react\/jsx-dev-runtime$/, replacement: require.resolve("react/jsx-dev-runtime") },
        { find: /^react$/, replacement: require.resolve("react") },
        { find: "@", replacement: path.join(APP, "src") },
      ],
    },
    build: { outDir: OUT, emptyOutDir: true, chunkSizeWarningLimit: 8000 },
  })
  // The data's images (assets/<file>), served next to the page so components can show them.
  if (fs.existsSync(path.join(ws, "assets"))) fs.cpSync(path.join(ws, "assets"), path.join(OUT, "assets"), { recursive: true })
} catch (e) {
  add("能渲染", `构建失败:${String(e.message ?? e).split("\n").slice(0, 6).join(" ")}`)
  finish()
  process.exit(0)
